-- One row per purchased table, including several tables within a single payment.
create table public.gala_order_tables (
  order_id uuid not null references public.gala_orders(id),
  line_index integer not null check(line_index between 0 and 9),
  tier text not null references public.gala_inventory(tier),
  seats integer not null check(seats between 8 and 10),
  primary key(order_id,line_index)
);
insert into public.gala_order_tables(order_id,line_index,tier,seats)
  select id,0,tier,8+(details->'purchase'->>'extraSeats')::integer
  from public.gala_orders where tier is not null and details->>'kind'='tables';
alter table public.gala_order_tables enable row level security;
revoke all on public.gala_order_tables from public,anon,authenticated;
grant select,insert on public.gala_order_tables to service_role;
create index gala_order_tables_tier on public.gala_order_tables(tier);

alter table public.gala_table_assignments add column line_index integer not null default 0;
alter table public.gala_table_assignments drop constraint gala_table_assignments_pkey;
alter table public.gala_table_assignments add primary key(order_id,line_index);
alter table public.gala_table_assignments add foreign key(order_id,line_index) references public.gala_order_tables(order_id,line_index);
alter table public.gala_assignment_events add column line_index integer not null default 0;
alter table public.gala_assignment_events drop constraint gala_assignment_events_order_id_revision_key;
alter table public.gala_assignment_events add unique(order_id,line_index,revision);

create or replace function public.gala_reserve(p_id uuid,p_hash text,p_details jsonb,p_amount integer,p_description text,p_tier text)
returns jsonb language plpgsql security invoker set search_path='' as $$
declare existing public.gala_orders; selections jsonb; selection jsonb; requested record; available integer; used integer;
begin
  perform pg_advisory_xact_lock(hashtextextended(p_id::text,0));
  select * into existing from public.gala_orders where id=p_id;
  if found then
    if existing.request_hash<>p_hash then raise exception 'Request ID reused with different details'; end if;
    return to_jsonb(existing);
  end if;
  selections:=case when p_details->>'kind'='cart' then p_details->'purchases'
    when p_details->>'kind'='tables' then jsonb_build_array(p_details->'purchase') else '[]'::jsonb end;
  if selections is null or jsonb_typeof(selections)<>'array' or jsonb_array_length(selections)>10 then
    raise exception 'Invalid cart selections';
  end if;
  if p_details->>'kind'='cart' and p_tier is not null then raise exception 'Invalid cart tier'; end if;
  for selection in select value from jsonb_array_elements(selections) loop
    if selection->>'product' in ('platinum','gold','silver') and
      ((selection->>'quantity')::integer is distinct from 1 or (selection->>'extraSeats')::integer not between 0 and 2
        or selection->>'extraSeats' is null) then raise exception 'Invalid table selection'; end if;
  end loop;
  -- Lock tiers in the same order for every cart. Every requested tier succeeds or the
  -- transaction rolls back; timestamps never release inventory without verified expiry.
  for requested in select value->>'product' as tier,count(*) as quantity from jsonb_array_elements(selections)
    where value->>'product' in ('platinum','gold','silver') group by value->>'product' order by value->>'product' loop
    select capacity into strict available from public.gala_inventory where tier=requested.tier for update;
    select count(*) into used from public.gala_order_tables t join public.gala_orders o on o.id=t.order_id
      where t.tier=requested.tier and o.status<>'expired';
    if used+requested.quantity>available then raise exception 'Table tier sold out or reserved'; end if;
  end loop;
  insert into public.gala_orders(id,request_hash,details,amount,description,tier)
    values(p_id,p_hash,p_details,p_amount,p_description,p_tier) returning * into existing;
  insert into public.gala_order_tables(order_id,line_index,tier,seats)
    select p_id,(position-1)::integer,value->>'product',8+(value->>'extraSeats')::integer
    from jsonb_array_elements(selections) with ordinality as s(value,position)
    where value->>'product' in ('platinum','gold','silver');
  return to_jsonb(existing);
end $$;

create function public.gala_inventory_counts()
returns jsonb language sql stable security invoker set search_path='' as $$
  select coalesce(jsonb_agg(row_data order by tier),'[]'::jsonb) from (
    select i.tier,i.capacity,i.board_confirmed,
      count(*) filter(where o.status in ('reserved','awaiting_payment')) as held,
      count(*) filter(where o.status='paid') as paid,
      greatest(0,i.capacity-count(*) filter(where o.status<>'expired')) as available
    from public.gala_inventory i left join public.gala_order_tables t on t.tier=i.tier
    left join public.gala_orders o on o.id=t.order_id group by i.tier
  ) row_data;
$$;

create function public.gala_assign_table_line(p_order uuid,p_number integer,p_revision integer,p_line integer)
returns jsonb language plpgsql security invoker set search_path='' as $$
declare purchase public.gala_orders; current_assignment public.gala_table_assignments; old_number integer;
begin
  if p_line is null or p_line not between 0 and 9 or p_revision is null or p_revision<0
    or (p_number is not null and p_number not between 1 and 999) then raise exception 'Invalid assignment'; end if;
  select * into purchase from public.gala_orders where id=p_order for update;
  if not found or purchase.status<>'paid' or not exists(
    select 1 from public.gala_order_tables where order_id=p_order and line_index=p_line
  ) then raise exception 'Only paid table purchases can be assigned'; end if;
  insert into public.gala_table_assignments(order_id,line_index) values(p_order,p_line) on conflict do nothing;
  select * into current_assignment from public.gala_table_assignments where order_id=p_order and line_index=p_line for update;
  if current_assignment.revision<>p_revision then raise exception 'Assignment changed; reload before editing'; end if;
  if current_assignment.table_number is not distinct from p_number then return to_jsonb(current_assignment); end if;
  old_number:=current_assignment.table_number;
  update public.gala_table_assignments set table_number=p_number,revision=revision+1,updated_at=now()
    where order_id=p_order and line_index=p_line returning * into current_assignment;
  insert into public.gala_assignment_events(order_id,line_index,previous_number,table_number,revision)
    values(p_order,p_line,old_number,p_number,current_assignment.revision);
  return to_jsonb(current_assignment);
end $$;
-- Existing clients and saved orders continue to address their original table.
create or replace function public.gala_assign_table(p_order uuid,p_number integer,p_revision integer)
returns jsonb language sql security invoker set search_path='' as $$
  select public.gala_assign_table_line(p_order,p_number,p_revision,0);
$$;
create or replace function public.gala_assignment_list()
returns jsonb language sql stable security invoker set search_path='' as $$
  select coalesce(jsonb_agg(row_data order by table_number nulls last,created_at,id,line_index),'[]'::jsonb) from (
    select o.id,t.line_index,t.tier,o.details->'contact' as buyer,t.seats,
      a.table_number,coalesce(a.revision,0) as revision,o.created_at
    from public.gala_orders o join public.gala_order_tables t on t.order_id=o.id
    left join public.gala_table_assignments a on a.order_id=o.id and a.line_index=t.line_index
    where o.status='paid'
  ) row_data;
$$;

revoke all on function public.gala_assign_table_line(uuid,integer,integer,integer),public.gala_inventory_counts() from public,anon,authenticated;
grant execute on function public.gala_assign_table_line(uuid,integer,integer,integer),public.gala_inventory_counts() to service_role;

-- Gift and staff function replacements follow; their existing grants are preserved.
create or replace function public.gala_set_gift_status(p_order uuid,p_recipient integer,p_status text,p_revision integer,p_reason text)
returns jsonb language plpgsql security invoker set search_path='' as $$
declare purchase public.gala_orders; current_gift public.gala_gift_fulfillment; previous text; old_rank integer; new_rank integer;
begin
  if p_recipient is null or p_recipient<0 or p_revision is null or p_revision<0
    or p_status is null or p_status not in ('pending','prepared','delivered') or length(coalesce(p_reason,''))>300 then
    raise exception 'Invalid gift update';
  end if;
  select * into purchase from public.gala_orders where id=p_order for update;
  if not found or purchase.status<>'paid' or (purchase.details->>'kind' not in ('gifts','cart') or coalesce(jsonb_array_length(purchase.details->'gifts'),0)=0) then
    raise exception 'Only paid gifts can be fulfilled';
  end if;
  if p_recipient >= jsonb_array_length(purchase.details->'gifts') then raise exception 'Unknown recipient'; end if;
  insert into public.gala_gift_fulfillment(order_id,recipient_index) values(p_order,p_recipient) on conflict do nothing;
  select * into current_gift from public.gala_gift_fulfillment where order_id=p_order and recipient_index=p_recipient for update;
  if current_gift.revision<>p_revision then raise exception 'Gift changed; refresh before editing'; end if;
  if current_gift.status=p_status then return to_jsonb(current_gift); end if;
  previous := current_gift.status;
  old_rank := array_position(array['pending','prepared','delivered'],previous);
  new_rank := array_position(array['pending','prepared','delivered'],p_status);
  if new_rank>old_rank+1 then raise exception 'Prepare gifts before handing them out'; end if;
  if new_rank<old_rank and length(btrim(coalesce(p_reason,'')))<3 then raise exception 'A correction reason is required'; end if;
  update public.gala_gift_fulfillment set status=p_status,revision=revision+1,updated_at=now()
    where order_id=p_order and recipient_index=p_recipient returning * into current_gift;
  insert into public.gala_gift_events(order_id,recipient_index,previous_status,status,revision,reason)
    values(p_order,p_recipient,previous,p_status,current_gift.revision,nullif(btrim(p_reason),''));
  return to_jsonb(current_gift);
end $$;

create or replace function public.gala_gift_list()
returns jsonb language sql stable security invoker set search_path='' as $$
  select coalesce(jsonb_agg(row_data order by student,order_id,recipient_index),'[]'::jsonb) from (
    select o.id as order_id,(g.position-1)::integer as recipient_index,o.details->'contact' as buyer,
      g.gift->>'student' as student,g.gift->>'grade' as grade,
      (g.gift->>'roses')::integer as roses,(g.gift->>'cookies')::integer as cookies,
      coalesce(f.status,'pending') as status,coalesce(f.revision,0) as revision
    from public.gala_orders o
    cross join lateral jsonb_array_elements(case when o.details->>'kind' in ('gifts','cart') then o.details->'gifts' else '[]'::jsonb end) with ordinality as g(gift,position)
    left join public.gala_gift_fulfillment f on f.order_id=o.id and f.recipient_index=g.position-1
    where o.status='paid' and o.details->>'kind' in ('gifts','cart')
  ) row_data;
$$;
create or replace function public.gala_staff_mutation(p_session text,p_operation text,p_args jsonb)
returns jsonb language plpgsql security invoker set search_path='' as $$
declare identity jsonb; result jsonb;
begin
  identity:=public.gala_staff_identity(p_session,false);
  perform set_config('gala.actor',identity->>'userId',true);
  case p_operation
    when 'gala_assign_table' then result:=public.gala_assign_table_line((p_args->>'p_order')::uuid,(p_args->>'p_number')::integer,(p_args->>'p_revision')::integer,coalesce((p_args->>'p_line')::integer,0));
    when 'gala_set_gift_status' then result:=public.gala_set_gift_status((p_args->>'p_order')::uuid,(p_args->>'p_recipient')::integer,p_args->>'p_status',(p_args->>'p_revision')::integer,p_args->>'p_reason');
    when 'gala_set_invitation_status' then result:=public.gala_set_invitation_status((p_args->>'p_request')::uuid,(p_args->>'p_recipient')::integer,p_args->>'p_status',(p_args->>'p_revision')::integer,p_args->>'p_reason');
    when 'gala_set_invitation_address' then result:=public.gala_set_invitation_address((p_args->>'p_request')::uuid,(p_args->>'p_recipient')::integer,p_args->'p_address',(p_args->>'p_revision')::integer,p_args->>'p_reason');
    when 'gala_resolve_invitation_duplicate' then result:=public.gala_resolve_invitation_duplicate((p_args->>'p_request')::uuid,(p_args->>'p_recipient')::integer,(p_args->>'p_revision')::integer,p_args->>'p_decision',(p_args->>'p_target')::uuid,(p_args->>'p_target_recipient')::integer,(p_args->>'p_target_revision')::integer,p_args->>'p_reason');
    when 'gala_retry_recovery' then perform public.gala_retry_recovery((p_args->>'p_order')::uuid,p_args->>'p_reason'); result:='null'::jsonb;
    else raise exception 'Unsupported staff operation';
  end case;
  perform set_config('gala.actor','',true);
  return result;
end $$;
notify pgrst,'reload schema';

-- Source: 012_gala_ledger.sql; normalized SHA-256: 0771f25a9b7d0a67897ba86a9f85a5e9f907a3f81343f43615f77fc3a32568dd
do $$ begin
  if not exists(select 1 from public.gala_environment where id=1 and name='osg-gala-production') then
    raise exception 'Production marker required';
  end if;
end $$;

-- One SQL statement sees orders, payment confirmations and accounting history at
-- one database snapshot. JSON aggregation avoids PostgREST's row response limit.
create function public.gala_ledger_snapshot() returns jsonb
language sql stable security invoker set search_path='' as $$
  select jsonb_build_object(
    'orders', coalesce((select jsonb_agg(jsonb_build_object(
      'id', o.id, 'details', o.details, 'amount', o.amount, 'currency', o.currency,
      'status', o.status, 'created_at', o.created_at,
      'stripe_session_id', o.stripe_session_id, 'payment_intent_id', o.payment_intent_id,
      'confirmed_at', (select min(e.created_at) from public.gala_payment_events e where e.order_id=o.id and e.state='paid')
    ) order by o.created_at, o.id) from public.gala_orders o), '[]'::jsonb),
    'accounting', coalesce((select jsonb_agg(jsonb_build_object(
      'order_id', a.order_id, 'status', a.status, 'dispatched_at', a.dispatched_at,
      'receipt_id', a.receipt_id, 'realm_id', a.realm_id
    ) order by a.order_id) from public.gala_accounting_outbox a), '[]'::jsonb)
  );
$$;
revoke all on function public.gala_ledger_snapshot() from public, anon, authenticated;
grant execute on function public.gala_ledger_snapshot() to service_role;

-- Source: 013_gala_final_total.sql; normalized SHA-256: b64a310c56455a38cc05dd9949c2d6e92f18eab585ed044444267455eefe31d9
do $$ begin
  if not exists(select 1 from public.gala_environment where id=1 and name='osg-gala-production') then
    raise exception 'Production marker required';
  end if;
end $$;

create table public.gala_final_total (
  id uuid primary key,
  gala text not null unique check(gala='2027'),
  revision text not null check(revision ~ '^[a-f0-9]{64}$'),
  source jsonb not null,
  lines jsonb not null,
  amount bigint not null check(amount>0),
  realm_id text not null check(realm_id ~ '^[0-9]+$'),
  mapping jsonb not null,
  payload jsonb not null,
  actor text not null,
  created_at timestamptz not null default now(),
  status text not null default 'prepared' check(status in ('prepared','processing','synced','review')),
  lease_owner uuid, lease_until timestamptz,
  dispatched_at timestamptz, receipt_id text, synced_at timestamptz,
  attempts integer not null default 0, last_error text,
  unique(realm_id,receipt_id)
);
create table public.gala_final_total_orders (
  order_id uuid primary key references public.gala_orders(id),
  batch_id uuid not null references public.gala_final_total(id),
  amount bigint not null check(amount>0),
  payment_intent_id text not null unique,
  stripe_session_id text not null unique
);
alter table public.gala_final_total enable row level security;
alter table public.gala_final_total_orders enable row level security;
revoke all on public.gala_final_total,public.gala_final_total_orders from public,anon,authenticated,service_role;
grant select on public.gala_final_total,public.gala_final_total_orders to service_role;

-- Serializes finalization against all order and old per-order accounting writes.
-- A frozen final batch closes checkout creation even if dispatch needs review.
create or replace function public.gala_final_sales_guard() returns trigger
language plpgsql security definer set search_path='' as $$
begin
  if exists(select 1 from public.gala_final_total) then
    -- Late verified webhook/recovery replays may touch updated_at or try the
    -- existing outbox INSERT ON CONFLICT. They cannot change financial data.
    if TG_TABLE_NAME='gala_orders' and TG_OP='UPDATE'
      and (to_jsonb(new)-'updated_at')=(to_jsonb(old)-'updated_at') then return new; end if;
    if TG_TABLE_NAME='gala_accounting_outbox' and TG_OP='INSERT' then
      if exists(select 1 from public.gala_accounting_outbox where order_id=new.order_id) then return null; end if;
    end if;
    raise exception 'Gala sales closed for final accounting';
  end if;
  if TG_OP='DELETE' then return old; end if;
  return new;
end $$;
create trigger gala_final_orders_guard before insert or update or delete on public.gala_orders
  for each row execute function public.gala_final_sales_guard();
create trigger gala_final_accounting_guard before insert or update or delete on public.gala_accounting_outbox
  for each row execute function public.gala_final_sales_guard();

create function public.gala_final_prepare(p_id uuid,p_revision text,p_source jsonb,p_lines jsonb,
  p_mapping jsonb,p_payload jsonb,p_actor text) returns jsonb
language plpgsql security definer set search_path='' as $$
declare current_source jsonb; total bigint; n integer; job public.gala_final_total;
begin
  lock table public.gala_orders in share row exclusive mode;
  lock table public.gala_accounting_outbox in share row exclusive mode;
  select * into job from public.gala_final_total;
  if found then raise exception 'Final total already exists; recover the saved batch'; end if;
  current_source := public.gala_ledger_snapshot();
  if current_source is distinct from p_source then raise exception 'Ledger changed; refresh before finalizing'; end if;
  if exists(select 1 from public.gala_orders where status not in ('paid','expired')) then raise exception 'Unresolved orders'; end if;
  if exists(select 1 from public.gala_accounting_outbox where status<>'pending' or dispatched_at is not null
    or receipt_id is not null or realm_id is not null or payload is not null or lease_until is not null) then
    raise exception 'Earlier accounting requires review';
  end if;
  if exists(select 1 from public.gala_orders o where o.status='paid' and (o.currency<>'usd'
    or o.payment_intent_id is null or o.stripe_session_id is null
    or not exists(select 1 from public.gala_accounting_outbox a where a.order_id=o.id)
    or not exists(select 1 from public.gala_payment_events e where e.order_id=o.id and e.state='paid'))) then
    raise exception 'Paid evidence missing';
  end if;
  select sum(amount),count(*) into total,n from public.gala_orders where status='paid';
  if n=0 or total is null or total<=0 then raise exception 'Paid sales required'; end if;
  if jsonb_typeof(p_lines)<>'array' or jsonb_array_length(p_lines)=0
    or (select sum((l->>'amount')::bigint) from jsonb_array_elements(p_lines) l) is distinct from total
    or exists(select 1 from jsonb_array_elements(p_lines) l where l->>'status'<>'paid')
    or exists(select 1 from public.gala_orders o where o.status='paid' and o.amount is distinct from
      (select sum((l->>'amount')::bigint) from jsonb_array_elements(p_lines) l where l->>'orderId'=o.id::text))
    or exists(select 1 from jsonb_array_elements(p_lines) l where not exists
      (select 1 from public.gala_orders o where o.id::text=l->>'orderId' and o.status='paid')) then
    raise exception 'Invalid frozen ledger';
  end if;
  if jsonb_array_length(p_payload->'Line')<>1 or (p_payload#>>'{Line,0,Amount}')::numeric*100 is distinct from total::numeric
    or p_payload#>>'{CurrencyRef,value}' is distinct from 'USD'
    or p_payload#>>'{CustomerRef,value}' is distinct from p_mapping->>'customerId'
    or p_payload#>>'{DepositToAccountRef,value}' is distinct from p_mapping->>'clearingAccountId'
    or p_payload#>>'{Line,0,SalesItemLineDetail,ItemRef,value}' is distinct from p_mapping->>'itemId'
    or p_payload#>>'{Line,0,SalesItemLineDetail,TaxCodeRef,value}' is distinct from 'NON'
    or length(p_actor) not between 1 and 150 then raise exception 'Invalid final receipt'; end if;
  insert into public.gala_final_total(id,gala,revision,source,lines,amount,realm_id,mapping,payload,actor)
    values(p_id,'2027',p_revision,p_source,p_lines,total,p_mapping->>'realmId',p_mapping,p_payload,p_actor) returning * into job;
  insert into public.gala_final_total_orders(order_id,batch_id,amount,payment_intent_id,stripe_session_id)
    select id,p_id,amount,payment_intent_id,stripe_session_id from public.gala_orders where status='paid';
  return to_jsonb(job);
end $$;

create function public.gala_final_claim(p_id uuid,p_owner uuid) returns jsonb
language plpgsql security definer set search_path='' as $$
declare job public.gala_final_total;
begin
  select * into strict job from public.gala_final_total where id=p_id for update;
  if job.status='synced' or job.lease_until>now() then return null; end if;
  update public.gala_final_total set status='processing',lease_owner=p_owner,lease_until=now()+interval '2 minutes',attempts=attempts+1
    where id=p_id returning * into job;
  return to_jsonb(job) || jsonb_build_object('order_id',job.id);
end $$;
create function public.gala_final_dispatch(p_id uuid,p_owner uuid) returns void
language plpgsql security definer set search_path='' as $$
begin
  update public.gala_final_total set dispatched_at=now() where id=p_id and lease_owner=p_owner
    and lease_until>now() and status='processing' and dispatched_at is null;
  if not found then raise exception 'Dispatch not allowed'; end if;
end $$;
create function public.gala_final_finish(p_id uuid,p_owner uuid,p_receipt text) returns void
language plpgsql security definer set search_path='' as $$
begin
  if p_receipt !~ '^[0-9]+$' then raise exception 'Receipt required'; end if;
  update public.gala_final_total set status='synced',receipt_id=p_receipt,synced_at=now(),last_error=null,lease_owner=null,lease_until=null
    where id=p_id and lease_owner=p_owner and lease_until>now() and status='processing';
  if not found then raise exception 'Lease lost'; end if;
end $$;
create function public.gala_final_review(p_id uuid,p_owner uuid,p_code text) returns void
language plpgsql security definer set search_path='' as $$
begin
  update public.gala_final_total set status='review',last_error='verification_required',lease_owner=null,lease_until=null
    where id=p_id and lease_owner=p_owner and lease_until>now() and status='processing';
end $$;
revoke all on function public.gala_final_sales_guard(),public.gala_final_prepare(uuid,text,jsonb,jsonb,jsonb,jsonb,text),
  public.gala_final_claim(uuid,uuid),public.gala_final_dispatch(uuid,uuid),public.gala_final_finish(uuid,uuid,text),public.gala_final_review(uuid,uuid,text)
  from public,anon,authenticated;
grant execute on function public.gala_final_prepare(uuid,text,jsonb,jsonb,jsonb,jsonb,text),public.gala_final_claim(uuid,uuid),
  public.gala_final_dispatch(uuid,uuid),public.gala_final_finish(uuid,uuid,text),public.gala_final_review(uuid,uuid,text) to service_role;

-- Source: 014_gala_unlimited_manual_accounting.sql; normalized SHA-256: 78de0330355fa25006fc373ef830b66f5240d8bc2bbd58d3bfa2eb796111bbe0
-- NULL capacity means unlimited; a nonnegative integer restores a finite cap.
-- Existing paid/pending orders are never canceled by a capacity change.

do $$ begin
  if not exists(select 1 from public.gala_environment where id=1 and name='osg-gala-production') then
    raise exception 'Production marker required';
  end if;
end $$;
alter table public.gala_inventory alter column capacity drop not null;
alter table public.gala_inventory drop constraint gala_inventory_board_confirmed_check;
comment on column public.gala_inventory.capacity is 'NULL = unlimited; nonnegative integer = maximum paid plus pending tables.';
update public.gala_inventory set capacity=null,board_confirmed=true;

create or replace function public.gala_reserve(p_id uuid,p_hash text,p_details jsonb,p_amount integer,p_description text,p_tier text)
returns jsonb language plpgsql security invoker set search_path='' as $$
declare existing public.gala_orders; selections jsonb; selection jsonb; requested record; available integer; used integer;
begin
  perform pg_advisory_xact_lock(hashtextextended(p_id::text,0));
  select * into existing from public.gala_orders where id=p_id;
  if found then
    if existing.request_hash<>p_hash then raise exception 'Request ID reused with different details'; end if;
    return to_jsonb(existing);
  end if;
  selections:=case when p_details->>'kind'='cart' then p_details->'purchases'
    when p_details->>'kind'='tables' then jsonb_build_array(p_details->'purchase') else '[]'::jsonb end;
  if selections is null or jsonb_typeof(selections)<>'array' or jsonb_array_length(selections)>10 then
    raise exception 'Invalid cart selections';
  end if;
  if p_details->>'kind'='cart' and p_tier is not null then raise exception 'Invalid cart tier'; end if;
  for selection in select value from jsonb_array_elements(selections) loop
    if selection->>'product' in ('platinum','gold','silver') and
      ((selection->>'quantity')::integer is distinct from 1 or (selection->>'extraSeats')::integer not between 0 and 2
        or selection->>'extraSeats' is null) then raise exception 'Invalid table selection'; end if;
  end loop;
  -- Lock tiers in the same order for every cart. Every requested tier succeeds or the
  -- transaction rolls back; timestamps never release inventory without verified expiry.
  for requested in select value->>'product' as tier,count(*) as quantity from jsonb_array_elements(selections)
    where value->>'product' in ('platinum','gold','silver') group by value->>'product' order by value->>'product' loop
    select capacity into strict available from public.gala_inventory where tier=requested.tier for update;
    select count(*) into used from public.gala_order_tables t join public.gala_orders o on o.id=t.order_id
      where t.tier=requested.tier and o.status<>'expired';
    if available is not null and used+requested.quantity>available then raise exception 'Table tier sold out or reserved'; end if;
  end loop;
  insert into public.gala_orders(id,request_hash,details,amount,description,tier)
    values(p_id,p_hash,p_details,p_amount,p_description,p_tier) returning * into existing;
  insert into public.gala_order_tables(order_id,line_index,tier,seats)
    select p_id,(position-1)::integer,value->>'product',8+(value->>'extraSeats')::integer
    from jsonb_array_elements(selections) with ordinality as s(value,position)
    where value->>'product' in ('platinum','gold','silver');
  return to_jsonb(existing);
end $$;

create or replace function public.gala_inventory_counts()
returns jsonb language sql stable security invoker set search_path='' as $$
  select coalesce(jsonb_agg(row_data order by tier),'[]'::jsonb) from (
    select i.tier,i.capacity,i.board_confirmed,
      count(*) filter(where o.status in ('reserved','awaiting_payment')) as held,
      count(*) filter(where o.status='paid') as paid,
      case when i.capacity is null then null else greatest(0,i.capacity-count(*) filter(where o.status<>'expired')) end as available,
      i.capacity is null as unlimited,
      case when i.capacity is null then false else count(*) filter(where o.status<>'expired')>i.capacity end as over_limit
    from public.gala_inventory i left join public.gala_order_tables t on t.tier=i.tier
    left join public.gala_orders o on o.id=t.order_id group by i.tier
  ) row_data;
$$;

create or replace function public.gala_apply_payment(p_id uuid, p_session text, p_state text, p_payment text, p_event text)
returns jsonb language plpgsql security invoker set search_path = '' as $$
declare existing public.gala_orders; recorded public.gala_payment_events;
begin
  select * into strict existing from public.gala_orders where id = p_id for update;
  if p_session is null or p_session !~ '^cs_live_[A-Za-z0-9]+$' then raise exception 'Live session required'; end if;
  if existing.stripe_session_id is not null and existing.stripe_session_id <> p_session then raise exception 'Session mismatch'; end if;
  if p_state not in ('paid','expired') or p_state is null then raise exception 'Invalid transition'; end if;
  if p_state = 'paid' and (p_payment is null or p_payment not like 'pi_%') then raise exception 'Verified payment required'; end if;
  if existing.status in ('paid','expired') and existing.status <> p_state then raise exception 'Conflicting terminal state requires review'; end if;
  if existing.payment_intent_id is not null and existing.payment_intent_id is distinct from p_payment then raise exception 'Payment mismatch'; end if;
  select * into recorded from public.gala_payment_events where event_id = p_event;
  if found then
    if recorded.order_id <> p_id or recorded.state <> p_state then raise exception 'Event conflict'; end if;
    return to_jsonb(existing);
  end if;
  insert into public.gala_payment_events(event_id, order_id, state) values(p_event, p_id, p_state);
  update public.gala_orders set stripe_session_id = p_session, status = p_state,
    payment_intent_id = p_payment, updated_at = now() where id = p_id returning * into existing;
  return to_jsonb(existing);
end $$;


-- Preserve every historical receipt/batch, but remove application access to connection
-- tokens and all retired accounting write RPCs. No other QuickBooks integration changes.
update public.gala_qb_connection set sealed_tokens=null,lock_owner=null,lock_until=null;
revoke all on public.gala_qb_connection from service_role;
revoke insert,update,delete,truncate on public.gala_accounting_outbox from service_role;
do $$ declare fn regprocedure; begin
  for fn in select p.oid::regprocedure from pg_proc p join pg_namespace n on n.oid=p.pronamespace
    where n.nspname='public' and (p.proname like 'gala_qb_%' or p.proname like 'gala_accounting_%'
      or p.proname in ('gala_final_prepare','gala_final_claim','gala_final_dispatch','gala_final_finish','gala_final_review'))
  loop
    execute format('revoke all on function %s from public,anon,authenticated,service_role',fn);
  end loop;
end $$;

-- Included at the end of the atomic fresh-install bundle. Not a standalone migration.
-- A database operator must explicitly open sales after the release is approved.
create table public.gala_operating_state (
  id integer primary key check(id=1),
  sales_open boolean not null default false,
  invitations_open boolean not null default false
);
insert into public.gala_operating_state(id) values(1);
alter table public.gala_operating_state enable row level security;
revoke all on public.gala_operating_state from public,anon,authenticated,service_role;
grant select on public.gala_operating_state to service_role;

create function public.gala_require_open() returns trigger
language plpgsql security definer set search_path='' as $$
declare allowed boolean;
begin
  -- Definer rights allow locking this row without granting application UPDATE.
  -- Share lock keeps the setting stable until this reservation commits. Closing
  -- sales waits for in-flight reservations; payment/recovery updates remain valid.
  if tg_table_name='gala_orders' then
    select sales_open into allowed from public.gala_operating_state where id=1 for share;
  elsif tg_table_name='gala_invitation_requests' then
    select invitations_open into allowed from public.gala_operating_state where id=1 for share;
  end if;
  if allowed is distinct from true then raise exception 'Gala submissions are closed'; end if;
  return new;
end $$;
create trigger gala_open_sales before insert on public.gala_orders
  for each row execute function public.gala_require_open();
create trigger gala_open_invitations before insert on public.gala_invitation_requests
  for each row execute function public.gala_require_open();

-- Existing customer RPCs insert then attach the owner in one transaction.
-- Check the final stored row at commit, so even service-side coding mistakes
-- cannot persist an unowned order/request or erase an existing owner's identity.
create function public.gala_require_customer() returns trigger
language plpgsql security invoker set search_path='' as $$
declare owner_hash text;
begin
  if tg_table_name='gala_orders' then
    select customer_hash into owner_hash from public.gala_orders where id=new.id;
  elsif tg_table_name='gala_invitation_requests' then
    select customer_hash into owner_hash from public.gala_invitation_requests where id=new.id;
  end if;
  if owner_hash is null or owner_hash !~ '^[a-f0-9]{64}$' then raise exception 'Customer ownership required'; end if;
  if tg_op='UPDATE' and old.customer_hash is not null and owner_hash is distinct from old.customer_hash then
    raise exception 'Customer ownership cannot change';
  end if;
  return null;
end $$;
create constraint trigger gala_order_owner after insert or update on public.gala_orders
  deferrable initially deferred for each row execute function public.gala_require_customer();
create constraint trigger gala_invitation_owner after insert or update on public.gala_invitation_requests
  deferrable initially deferred for each row execute function public.gala_require_customer();

-- Shared-password administration records the role, not a made-up person's name.
-- Named-account tables remain empty for schema compatibility, but their old
-- mutation/session APIs are unavailable to the production application.
revoke all on public.gala_staff,public.gala_staff_sessions from service_role;
revoke all on function public.gala_staff_identity(text,boolean),
  public.gala_create_staff_session(uuid,text,integer),public.gala_staff_mutation(text,text,jsonb) from service_role;
revoke insert,update,delete,truncate on public.gala_environment from service_role;
revoke all on function public.gala_require_open(),public.gala_require_customer() from public,anon,authenticated;

-- All tables/functions in this dedicated project are private. Revoke defaults
-- as well as the current grants so future migrations do not silently expose data.
revoke all on all tables in schema public from public,anon,authenticated;
revoke all on all sequences in schema public from public,anon,authenticated;
revoke all on all functions in schema public from public,anon,authenticated;
alter default privileges in schema public revoke all on tables from public,anon,authenticated;
alter default privileges in schema public revoke all on sequences from public,anon,authenticated;
alter default privileges in schema public revoke execute on functions from public,anon,authenticated;

do $$ begin
  if exists(select 1 from public.gala_orders) or exists(select 1 from public.gala_invitation_requests)
    or exists(select 1 from public.gala_staff) or exists(select 1 from public.gala_payment_events)
    or exists(select 1 from public.gala_accounting_outbox) or exists(select 1 from public.gala_final_total)
    or exists(select 1 from public.gala_qb_connection where sealed_tokens is not null) then
    raise exception 'Fresh production installation must contain no business/test records or credentials';
  end if;
  if (select count(*) from public.gala_inventory where capacity is null and board_confirmed)<>3 then
    raise exception 'Board-approved unlimited inventory required';
  end if;
end $$;
commit;
